// Every export takes nothing and returns nothing. The contract states that
// `listen` registers a cleanup and `startTickerAlways` a computation on the
// caller's owner on every call, that `startTicker` may register a
// computation, and that `startTickerSilent` registers nothing.
//
// The signatures are `tsc`-clean on purpose: calling any of them anywhere is
// well typed, so whatever the checker reports here is nothing `tsc` reports.
export declare function listen(): void;
export declare function startTicker(): void;
export declare function startTickerAlways(): void;
export declare function startTickerSilent(): void;
